def safe_name(name: str) -> bool:
    """True when name is one plain path component: non-empty, not '.' or '..', with no slash, backslash or NUL."""
    ex safe_name("notes.txt") == True
    ex safe_name("../secret") == False
    ex safe_name("a/b") == False
    ex safe_name("") == False
    if name == "" or name == "." or name == "..":
        return False
    for ch in name.chars():
        if ch == "/" or ch == "\\" or ch == "\0":
            return False
    return True

def can_read(name: str) -> bool uses fs:
    """True when name is a safe name and fs, confined to the notes directory, can open it as a readable file. A missing or unreadable file gives False."""
    post not out or safe_name(name)
    if not safe_name(name):
        return False
    text = fs.read_text(name) else return False
    return True

def count_readable(names: list[str]) -> int uses fs:
    """Number of entries in names that can be read from the notes directory. Names are untrusted; the function narrows fs with `with fs = fs.sub("notes"):` so no name can reach a file outside notes."""
    post out >= 0 and out <= names.len()
    count = 0
    with fs = fs.sub("notes"):
        for name in names:
            if can_read(name):
                count += 1
    return count
